// Projects — single source for the homepage Selected Work, /projects and /projects/[slug].
// Images: public/images/work/<slug>/ (generated by scripts/optimize-projects.mjs from the git-ignored raw folder).
// TODO(AJ): add 1–2 sentences per project on what YOU were responsible for (`description`).
export type Platform = 'Astro' | 'Webflow' | 'Framer';

export interface Project {
  slug: string;
  name: string;
  platform: Platform;
  url: string;
  role: string;
  contribution: string[];
  description?: string;
  featured?: boolean;
  hasDesktopFullpage: boolean;
}

